<?php defined('ABSPATH') || exit;$d=$args['data'];$contexts=array_merge($d['lens']['availability_contexts'],$d['lens']['offering_contexts']);if(!$d['suites']&&!$contexts)return; ?>
<section id="property-availability" class="dossier-section" aria-labelledby="availability-heading">
 <div class="dossier-section-heading"><p class="dossier-eyebrow">SPACE / OFFERING</p><div><h2 id="availability-heading">Find your room<br>to move.</h2><p>Review the listed spaces and confirm current terms with Aspire.</p></div></div>
 <div class="dossier-suites"><?php foreach($d['suites'] as $i=>$suite): ?><article aria-label="<?php echo esc_attr($suite['suite_name']?:'Listed space '.($i+1)); ?>"><div><p class="dossier-eyebrow"><?php echo esc_html($suite['suite_name']?:'Listed space '.($i+1)); ?></p><?php if($suite['square_feet']): ?><h3><?php echo esc_html($suite['square_feet']); ?> <small>SF</small></h3><?php endif; ?></div><dl><?php foreach(array('rate'=>'Rate','rate_type'=>'Rate basis','former_use'=>'Former use','availability_status'=>'Availability','notes'=>'Listing context') as $key=>$label):if($suite[$key]==='')continue; ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($suite[$key]); ?></dd></div><?php endforeach; ?></dl><a href="tel:+17139332001" class="dossier-text-link">ASK ABOUT THIS SPACE →</a></article><?php endforeach; ?></div>
 <?php foreach($contexts as $context): ?><article class="dossier-offering"><h3><?php echo esc_html($context['label']); ?></h3><dl><?php foreach($context['facts'] as $fact): ?><div><dt><?php echo esc_html($fact['label']); ?></dt><dd><?php echo esc_html($fact['value']); ?></dd></div><?php endforeach; ?></dl></article><?php endforeach; ?>
